def _row_index(seat_number):
    letters = "".join(ch for ch in seat_number if ch.isalpha()).upper()
    index = 0

    for ch in letters:
        index = index * 26 + (ord(ch) - 64)

    return index - 1


def assign_sections(apps, schema_editor):
    """Assign Gold/Silver sections and synchronize existing tickets."""
    Seat = apps.get_model("cinema", "Seat")
    Ticket = apps.get_model("cinema", "Ticket")
    Show = apps.get_model("cinema", "Show")

    db_alias = schema_editor.connection.alias

    shows = Show.objects.using(db_alias).select_related("hall").iterator()

    for show in shows:
        hall = show.hall
        row_count = -(-hall.total_seats // 10)
        first_gold_row = row_count - min(hall.gold_rows, row_count)

        gold_ids = [
            seat.id
            for seat in Seat.objects.using(db_alias).filter(show=show)
            if _row_index(seat.seat_number) >= first_gold_row
        ]

        if gold_ids:
            Seat.objects.using(db_alias).filter(
                id__in=gold_ids
            ).update(section="gold")

    tickets = Ticket.objects.using(db_alias).select_related("seat").iterator()

    for ticket in tickets:
        if ticket.section != ticket.seat.section:
            ticket.section = ticket.seat.section
            ticket.save(using=db_alias, update_fields=["section"])


